import { LARGE_PASTE_THRESHOLD } from "./constants";
import { classify } from "./classifier";
import { computeFinalTextStats, summarizeFinalText } from "./summarizer";
import type {
  FinalTextStats,
  InputEvent,
  ProvenanceKind,
  ProvenanceSummary,
  SessionStats,
  Verdict,
} from "./types";

export type ChangeHint = "typed" | "pasted" | "undo" | "redo" | "unknown";

export interface TrackerSnapshot {
  text: string;
  kinds: readonly ProvenanceKind[];
  events: readonly InputEvent[];
  sessionStats: SessionStats;
  finalTextStats: FinalTextStats;
  summary: ProvenanceSummary;
  verdict: Verdict;
  startedAt: number;
}

// Hard cap: stop recording new events past this count to bound JSON column size.
// Kinds and session stats continue updating correctly — only the event log is capped.
const EVENT_LOG_LIMIT = 50_000;

export class ProvenanceTracker {
  private text: string;
  private kinds: ProvenanceKind[];
  private events: InputEvent[] = [];
  private sessionStats: SessionStats;
  private startedAt: number;

  constructor(initialText = "", now = Date.now()) {
    this.text = initialText;
    this.kinds = Array.from<ProvenanceKind>({
      length: initialText.length,
    }).fill("unknown");
    this.startedAt = now;
    this.sessionStats = emptySessionStats(initialText.length);
  }

  applyChange(newText: string, hint: ChangeHint, now = Date.now()): void {
    const oldText = this.text;
    const { start, removedLength, insertedLength } = diffSpan(oldText, newText);
    const insertedKind = kindForHint(hint);

    this.kinds.splice(
      start,
      removedLength,
      ...Array.from<ProvenanceKind>({ length: insertedLength }).fill(
        insertedKind,
      ),
    );
    this.text = newText;

    const t = now - this.startedAt;

    const canLog = this.events.length < EVENT_LOG_LIMIT;

    if (insertedLength > 0) {
      if (hint === "pasted") {
        const large = insertedLength >= LARGE_PASTE_THRESHOLD;
        this.sessionStats.pastedChars += insertedLength;
        this.sessionStats.pasteEvents += 1;
        if (large) this.sessionStats.largePasteEvents += 1;
        if (canLog)
          this.events.push({ kind: "paste", t, chars: insertedLength, large });
      } else if (hint === "typed") {
        this.sessionStats.typedChars += insertedLength;
        if (canLog)
          this.events.push({ kind: "type", t, chars: insertedLength });
      } else if (hint === "undo") {
        this.sessionStats.undoEvents += 1;
        if (canLog)
          this.events.push({ kind: "undo", t, chars: insertedLength });
      } else if (hint === "redo") {
        this.sessionStats.redoEvents += 1;
        if (canLog)
          this.events.push({ kind: "redo", t, chars: insertedLength });
      }
    }

    if (removedLength > 0) {
      this.sessionStats.deleteEvents += 1;
      this.sessionStats.deletedChars += removedLength;
      if (hint !== "undo" && hint !== "redo") {
        if (canLog)
          this.events.push({ kind: "delete", t, chars: removedLength });
      }
    }

    this.sessionStats.totalChars = newText.length;
    this.sessionStats.durationMs = Math.max(0, now - this.startedAt);
  }

  snapshot(now = Date.now()): TrackerSnapshot {
    const finalTextStats = computeFinalTextStats(this.kinds);
    const summary = summarizeFinalText(finalTextStats, this.kinds);

    return {
      text: this.text,
      kinds: this.kinds.slice(),
      events: this.events.slice(),
      sessionStats: {
        ...this.sessionStats,
        totalChars: this.text.length,
        durationMs: Math.max(0, now - this.startedAt),
      },
      finalTextStats,
      summary,
      verdict: classify(finalTextStats, summary),
      startedAt: this.startedAt,
    };
  }
}

function diffSpan(oldText: string, newText: string) {
  let start = 0;
  const minLength = Math.min(oldText.length, newText.length);

  while (
    start < minLength &&
    oldText.charCodeAt(start) === newText.charCodeAt(start)
  ) {
    start += 1;
  }

  let suffix = 0;
  const maxSuffix = Math.min(oldText.length - start, newText.length - start);

  while (
    suffix < maxSuffix &&
    oldText.charCodeAt(oldText.length - 1 - suffix) ===
      newText.charCodeAt(newText.length - 1 - suffix)
  ) {
    suffix += 1;
  }

  return {
    start,
    removedLength: oldText.length - start - suffix,
    insertedLength: newText.length - start - suffix,
  };
}

function kindForHint(hint: ChangeHint): ProvenanceKind {
  if (hint === "typed") return "typed";
  if (hint === "pasted") return "pasted";
  return "unknown";
}

function emptySessionStats(totalChars: number): SessionStats {
  return {
    typedChars: 0,
    pastedChars: 0,
    pasteEvents: 0,
    largePasteEvents: 0,
    deleteEvents: 0,
    deletedChars: 0,
    undoEvents: 0,
    redoEvents: 0,
    totalChars,
    durationMs: 0,
  };
}
